import {insuranceFacts} from './insurance.js';
import {calcField as field,calcSelect as select,calcCheck as check,calcDisclosure as details} from './calculator-view.js';
const tri=[['unknown','Nie wiem — potrzebuję wskazówki'],['yes','Tak'],['no','Nie']];
export function insuranceQuestions(input,prefix){const title=prefix.split('.').reduce((o,k)=>o[k],input);title.insuranceFacts??=insuranceFacts({});const f=title.insuranceFacts,p=prefix+'.insuranceFacts.';let html='';
 if(title.occupation==='employee')html=select(input,p+'employmentConfirmed','Czy masz potwierdzoną umowę o pracę, która obejmuje tę datę?',tri)+field(input,p+'guaranteedPay','Kwota brutto zagwarantowana miesięcznie na etacie',{help:'Istotna, jeżeli masz również zlecenie lub działalność. Nie jest podstawą zasiłku.'});
 if(['contract','student'].includes(title.occupation))html=select(input,p+'student','Czy jesteś uczniem lub studentem?',tri)+select(input,p+'ownEmployer','Czy zlecenie jest z własnym pracodawcą lub wykonywane na jego rzecz?',tri)+select(input,p+'combinedBasis','Przy własnym pracodawcy: czy wpisana podstawa pracownicza obejmuje również zlecenie?',tri)+field(input,p+'contributionBase','Podstawa składek społecznych z tego zlecenia w miesiącu',{help:'Przy kilku zleceniach znaczenie mają kolejność tytułów i suma podstaw, a nie sama wypłata netto.'});
 if(title.occupation==='business')html=select(input,p+'businessForm','W jakiej formie wykonujesz działalność?',[['unknown','Jeszcze nie wiem'],['sole','Jednoosobowa działalność'],['cooperating','Osoba współpracująca'],['single-company','Jedyny wspólnik spółki z o.o.'],['multi-company','Wspólnik wieloosobowej spółki z o.o.'],['partnership','Inna spółka / forma działalności']])+field(input,p+'returnAfterMaternity','Koniec macierzyńskiego / data powrotu do innego tytułu, jeśli dotyczy',{type:'date'});
 if(['contract','student','business'].includes(title.occupation))html+=select(input,p+'emrCompulsory','Czy z tego tytułu obowiązkowo opłacane są emerytalne i rentowe?',tri)+select(input,p+'voluntaryRequested','Czy złożono wniosek o dobrowolne chorobowe?',tri)+select(input,p+'registered','Czy potwierdzono objęcie chorobowym?',tri)+field(input,p+'registeredAt','Data objęcia chorobowym z potwierdzenia',{type:'date'});
 if(title.occupation==='business')html+=f.suspensions.map((s,i)=>'<div class="calc-fields">'+field(input,p+'suspensions.'+i+'.from','Zawieszenie działalności od',{type:'date'})+field(input,p+'suspensions.'+i+'.to','Zawieszenie do / dzień przed wznowieniem',{type:'date'})+'</div>').join('')+`<button type="button" class="secondary" data-add-suspension="${prefix}">Dodaj okres zawieszenia</button>`;
 return html?details('Nie wiesz, jakie masz chorobowe? Ustalmy to z rodzaju pracy.',`<p>Chorobowe ZUS i zdrowotne NFZ to inne ubezpieczenia. Odpowiedzi pozwalają ustalić jednoznaczne przypadki; przy brakujących danych pokażemy sposób potwierdzenia.</p>${html}`):'';
}
